import React, { createContext, useContext } from "react";
import { loadFont as loadCinzel } from "@remotion/google-fonts/Cinzel";
import { loadFont as loadCormorant } from "@remotion/google-fonts/CormorantGaramond";
import { loadFont as loadQuattro } from "@remotion/google-fonts/Quattrocento";
import { AbsoluteFill, Img, OffthreadVideo, staticFile, useCurrentFrame } from "remotion";

// Vale dos Coqueirais — carrossel "Álbum do Vale" (23/10/2026), 1080×1350, um quadro = uma tela.
// Identidade do site (notas do cliente): verde-floresta, creme, papel, dourado, areia, musgo; Cormorant Garamond nos títulos,
// Cinzel no lugar da Trajan, Quattrocento no texto. Minimalista: fundo liso, foto como cópia de álbum, texto centralizado.
// O texto das telas é o do o diretor, sem mudar nada (só dividido entre título, corpo e destaque).
// v7 (23/10): correções de texto do cliente (prints do WhatsApp) nas telas 2 a 9; a tela 6 perdeu o cartão "Faltava o lado de quem contrata."
// v2 (pedido): "usar mais a inversão de cores da identidade" e "mais arredondamento". Os fundos se revezam entre
// mata, papel, areia e dourado, o destaque vem num cartão na cor invertida, e foto, legenda e rodapé ganharam cantos redondos.
// v3 (o diretor, com print do topo do site): "a primeira capa vamos deixar nessa identidade" e o dourado de fundo "não tá na id".
// Do CSS do site: --terra #B55219 é o destaque (botão e o itálico dos títulos); títulos em Trajan caixa alta (aqui Cinzel)
// com o trecho em <em> no Cormorant itálico 300, terracota, 1,22em; foto em arco (999px 999px 28px 28px); fundo creme.

export const { fontFamily: SERIF } = loadCormorant("normal", { weights: ["500", "600"], subsets: ["latin", "latin-ext"] });
export const { fontFamily: SERIF_IT } = loadCormorant("italic", { weights: ["300", "500", "600"], subsets: ["latin", "latin-ext"] });
export const { fontFamily: CAPS } = loadCinzel("normal", { weights: ["400", "600"], subsets: ["latin", "latin-ext"] });
export const { fontFamily: BODY } = loadQuattro("normal", { weights: ["400", "700"], subsets: ["latin", "latin-ext"] });

export const FOREST = "#1F2D16";
export const PAPER = "#FBF8F1";
export const CREAM = "#F5EFE3";
export const SAND = "#E7DCC6";
export const TERRA = "#B55219";
export const MOSS = "#545E46";
export const LADO = 120;
export const ALBUM_TELAS = 10;

// destaque = a cor invertida do fundo; margem = a borda da cópia de álbum
export type Fundo = "creme" | "areia" | "mata" | "terra";
export type Cores = { bg: string; tinta: string; suave: string; acento: string; margem: string; destaque: [string, string]; seta: [string, string]; logoClara: boolean };
export const FUNDOS: Record<Fundo, Cores> = {
  creme: { bg: CREAM, tinta: FOREST, suave: MOSS, acento: TERRA, margem: PAPER, destaque: [FOREST, CREAM], seta: [TERRA, CREAM], logoClara: false },
  areia: { bg: SAND, tinta: FOREST, suave: MOSS, acento: TERRA, margem: PAPER, destaque: [FOREST, CREAM], seta: [TERRA, CREAM], logoClara: false },
  mata: { bg: FOREST, tinta: CREAM, suave: "#CFC9B8", acento: TERRA, margem: CREAM, destaque: [CREAM, FOREST], seta: [CREAM, FOREST], logoClara: true },
  terra: { bg: TERRA, tinta: CREAM, suave: "#F3DCCB", acento: CREAM, margem: CREAM, destaque: [CREAM, FOREST], seta: [FOREST, CREAM], logoClara: true },
};
// grão leve por cima do fundo chapado (pedido na v4): ruído fractal em cinza contrastado, 12% de opacidade, que aparece
// tanto no creme quanto no verde
export const GRAO = `url("data:image/svg+xml;utf8,${encodeURIComponent("<svg xmlns='http://www.w3.org/2000/svg' width='240' height='240'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/><feComponentTransfer><feFuncR type='linear' slope='2' intercept='-0.5'/><feFuncG type='linear' slope='2' intercept='-0.5'/><feFuncB type='linear' slope='2' intercept='-0.5'/></feComponentTransfer></filter><rect width='100%' height='100%' filter='url(#n)' opacity='0.12'/></svg>")}")`;
export const CoresCtx = createContext<Cores>(FUNDOS.creme);
export const useCores = () => useContext(CoresCtx);

// foto como cópia de álbum: recorte em pixels da original (x, y, w, h) dentro de uma moldura de largura `largura`
export type Foto = { src: string; w: number; h: number; crop?: [number, number, number, number] };
export const Copia: React.FC<{ foto: Foto; largura: number; altura: number; arco?: boolean; children?: React.ReactNode }> = ({ foto, largura, altura, arco, children }) => {
  const { margem } = useCores();
  const [cx, cy, cw, ch] = foto.crop ?? [0, 0, foto.w, foto.h];
  const s = Math.max(largura / cw, altura / ch);
  return (
    <div style={{ background: margem, padding: 12, borderRadius: arco ? "999px 999px 38px 38px" : 38, boxShadow: "0 1px 2px rgba(20,30,14,0.10), 0 16px 40px rgba(20,30,14,0.16)", flexShrink: 0 }}>
      <div style={{ position: "relative", width: largura, height: altura, overflow: "hidden", borderRadius: arco ? "999px 999px 28px 28px" : 28 }}>
        <Img src={staticFile(`vale-album/${foto.src}`)} style={{ position: "absolute", width: foto.w * s, height: foto.h * s, left: -cx * s - (cw * s - largura) / 2, top: -cy * s - (ch * s - altura) / 2, maxWidth: "none" }} />
        {children}
      </div>
    </div>
  );
};

const MENINOS: Foto = { src: "meninos-borda.webp", w: 1600, h: 1088 };
const PISCINA: Foto = { src: "piscina-anos90.webp", w: 1600, h: 1078 };
const QUIOSQUE: Foto = { src: "quiosque-hoje.webp", w: 1200, h: 1600, crop: [0, 470, 1200, 760] };
const CAIO: Foto = { src: "meninos-borda.webp", w: 1600, h: 1088, crop: [930, 150, 670, 938] };

export const Legenda: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { suave, logoClara } = useCores();
  return (
    <div style={{ border: `2px solid ${suave}`, background: logoClara ? "rgba(20,30,14,0.5)" : "transparent", borderRadius: 999, padding: "10px 26px 9px", fontFamily: CAPS, fontWeight: 600, fontSize: 20, letterSpacing: "0.22em", color: suave, textTransform: "uppercase", marginTop: -6 }}>
      <span style={{ paddingLeft: "0.22em" }}>{children}</span>
    </div>
  );
};
export const Titulo: React.FC<{ size?: number; children: React.ReactNode; italico?: boolean; cor?: string }> = ({ size = 60, children, italico, cor }) => {
  const { tinta } = useCores();
  return (
    <div style={{ fontFamily: italico ? SERIF_IT : SERIF, fontStyle: italico ? "italic" : "normal", fontWeight: 600, fontSize: size, lineHeight: 1.1, letterSpacing: "-0.005em", color: cor ?? tinta, textWrap: "balance" } as React.CSSProperties}>
      {children}
    </div>
  );
};
// título como o h1 do site: Trajan (Cinzel) em caixa alta, e o trecho `em` no Cormorant itálico terracota, 1,22em
export const Caps: React.FC<{ size?: number; antes: string; em: string; cor?: string; corEm?: string; quebra?: boolean }> = ({ size = 56, antes, em, cor, corEm, quebra }) => {
  const { tinta } = useCores();
  return (
    <div style={{ fontFamily: CAPS, fontWeight: 400, fontSize: size, lineHeight: 1.12, letterSpacing: "0.01em", color: cor ?? tinta, textTransform: "uppercase", textWrap: "balance" } as React.CSSProperties}>
      {antes}
      {quebra ? <br /> : null}
      <span style={{ fontFamily: SERIF_IT, fontStyle: "italic", fontWeight: 300, fontSize: "1.22em", lineHeight: 0.9, letterSpacing: 0, textTransform: "none", color: corEm ?? TERRA }}>{em}</span>
    </div>
  );
};
export const Corpo: React.FC<{ size?: number; children: React.ReactNode; cor?: string }> = ({ size = 34, children, cor }) => {
  const { suave } = useCores();
  return <div style={{ fontFamily: BODY, fontSize: size, lineHeight: 1.42, color: cor ?? suave, textWrap: "pretty" } as React.CSSProperties}>{children}</div>;
};
// a frase de virada num cartão de canto redondo, na cor invertida do fundo
export const Destaque: React.FC<{ size?: number; children: React.ReactNode; corpo?: boolean }> = ({ size = 46, children, corpo }) => {
  const { destaque } = useCores();
  return (
    <div style={{ background: destaque[0], borderRadius: 40, padding: corpo ? "40px 52px" : "28px 48px 32px", maxWidth: "100%" }}>
      {corpo ? <Corpo size={size} cor={destaque[1]}>{children}</Corpo> : <Titulo size={size} italico cor={destaque[1]}>{children}</Titulo>}
    </div>
  );
};
export const Fio: React.FC = () => <div style={{ width: 56, height: 6, borderRadius: 3, background: useCores().acento, flexShrink: 0 }} />;

// v5 (o diretor): "fotos lá do vale com um leve degradê na parte de baixo e o texto com a mesma hierarquia" em algumas telas.
// Com `foto`, a foto do Vale cobre a tela, um degradê verde-floresta escurece a metade de baixo e o texto desce para lá.
// `zoom` aproxima a foto a partir da base, para o assunto (o campo, a mesa) subir para a metade de cima, que fica sem texto
// kit também dos carrosséis de novembro (src/Vale/novembro): `rotulo` e `total` mudam o rodapé de cada carrossel
export const Tela: React.FC<{ n: number; fundo?: Fundo; foto?: string; zoom?: number; children: React.ReactNode; gap?: number; rotulo?: string; total?: number }> = ({ n, fundo = "creme", foto, zoom = 1, children, gap = 40, rotulo = "ÁLBUM DO VALE", total = ALBUM_TELAS }) => {
  const f = FUNDOS[foto ? "mata" : fundo];
  return (
    <CoresCtx.Provider value={f}>
      <AbsoluteFill style={{ backgroundColor: f.bg, backgroundImage: GRAO, backgroundSize: "240px 240px", padding: `84px ${LADO}px 72px`, display: "flex", flexDirection: "column", alignItems: "center" }}>
        {foto ? (
          <>
            <Img src={staticFile(`vale-album/${foto}`)} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", transform: `scale(${zoom})`, transformOrigin: "50% 100%" }} />
            <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg, rgba(20,30,14,0.62) 0%, rgba(20,30,14,0.25) 12%, rgba(20,30,14,0) 22%, rgba(20,30,14,0) 30%, rgba(20,30,14,0.72) 52%, rgba(20,30,14,0.9) 72%, rgba(20,30,14,0.94) 100%)" }} />
          </>
        ) : null}
        {/* logo do site sem a frase de baixo (o recorte esconde "O espaço ideal para seu evento", pequena demais aqui) */}
        <div style={{ position: "relative", height: 95, width: 200, overflow: "hidden", flexShrink: 0 }}>
          <Img src={staticFile("vale-album/logo-site.png")} style={{ display: "block", width: 200, height: "auto", filter: f.logoClara ? "brightness(0) invert(1)" : undefined, opacity: f.logoClara ? 0.92 : 1 }} />
        </div>
        <div style={{ position: "relative", flex: 1, minHeight: 0, width: "100%", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: foto ? "flex-end" : "center", textAlign: "center", gap, paddingBottom: foto ? 44 : 0 }}>{children}</div>
        <div style={{ position: "relative", width: "100%", display: "flex", justifyContent: "space-between", alignItems: "center", flexShrink: 0, height: 56 }}>
          <div style={{ fontFamily: CAPS, fontWeight: 600, fontSize: 19, letterSpacing: "0.24em", color: f.suave }}>{rotulo}</div>
          <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
            <div style={{ fontFamily: CAPS, fontWeight: 600, fontSize: 19, letterSpacing: "0.12em", color: f.suave }}>{String(n).padStart(2, "0")} / {String(total).padStart(2, "0")}</div>
            {n < total ? (
              <div style={{ width: 56, height: 56, borderRadius: "50%", background: f.seta[0], display: "flex", alignItems: "center", justifyContent: "center" }}>
                <svg width="26" height="16" viewBox="0 0 40 24" fill="none" stroke={f.seta[1]} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M2 12h35M27 3l10 9-10 9" />
                </svg>
              </div>
            ) : null}
          </div>
        </div>
      </AbsoluteFill>
    </CoresCtx.Provider>
  );
};

// capa no desenho do topo do site (sobrancelha em caixa alta, título Trajan + itálico terracota); v4: a foto volta a ser a
// cópia de retrato inteira, sem o arco, para os dois meninos aparecerem por completo
// capa em vídeo (23/10): a mesma tela com a foto animada na Magnific (Kling, 5 s) por cima da cópia
const T1: React.FC<{ video?: boolean }> = ({ video }) => (
  <Tela n={1} gap={0}>
    <div style={{ fontFamily: CAPS, fontWeight: 400, fontSize: 21, letterSpacing: "0.3em", color: MOSS }}>
      <span style={{ paddingLeft: "0.3em" }}>ÁLBUM DO VALE · VARGEM PEQUENA, RJ</span>
    </div>
    <div style={{ marginTop: 30 }}>
      <Caps size={62} antes="Um desses meninos virou o dono do Vale, " em="qual deles você acha que foi?" />
    </div>
    <div style={{ marginTop: 52 }}>
      <Copia foto={MENINOS} largura={816} altura={555}>
        {video ? <OffthreadVideo src={staticFile("vale-album/capa-meninos-magnific.mp4")} muted style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} /> : null}
      </Copia>
    </div>
  </Tela>
);

const T2 = () => (
  <Tela n={2} gap={32}>
    <Copia foto={PISCINA} largura={812} altura={460} />
    <Legenda>Vargem Pequena · anos 90</Legenda>
    <Titulo size={50}>O sítio onde ele cresceu nos anos 90 é o mesmo que hoje recebe a sua festa...</Titulo>
    <Corpo>E o carinho que ele sente pelo espaço é o que moldou a forma de entendermos cada evento.</Corpo>
    <Destaque size={40}>Vem abrir o álbum com a gente.</Destaque>
  </Tela>
);

// o círculo marca o menino da direita (cabeça em ~1245, 445 da foto original)
const T3 = () => {
  const larg = 812, alt = 552, s = larg / 1600;
  return (
    <Tela n={3} fundo="areia" gap={40}>
      <Copia foto={MENINOS} largura={larg} altura={alt}>
        <div style={{ position: "absolute", left: 1245 * s - 118, top: 450 * s - 118, width: 236, height: 236, borderRadius: "50%", border: `5px solid ${TERRA}`, boxShadow: "0 0 0 1px rgba(255,255,255,0.35)" }} />
      </Copia>
      <Caps size={56} antes="É o da direita, " em="o Caio." />
      <Fio />
      <Corpo>A história dele com o sítio começa em 1992, quando os pais compraram um terreno em Vargem Pequena, onde só existia mato naquela região...</Corpo>
    </Tela>
  );
};

const T4 = () => (
  <Tela n={4} foto="montanhas.jpg" zoom={1.45} gap={34}>
    <Titulo size={54}>Como o pai e o avô do Caio trabalhavam com parque itinerante, eles levaram a alegria dos parques para o sítio.</Titulo>
    <Fio />
    <Corpo size={36}>Isso fez com que o Caio passasse semanas inteiras jogando bola no sítio com os funcionários, até o Vale virar parte da infância dele.</Corpo>
    <Destaque size={44}>Mas a família foi tomando outros rumos...</Destaque>
  </Tela>
);

const T5 = () => (
  <Tela n={5} gap={32}>
    <Copia foto={QUIOSQUE} largura={812} altura={500} />
    <Legenda>O quiosque</Legenda>
    <Titulo size={48}>...E o sítio foi ficando de lado, esquecido, mas a ligação do Caio com o lugar continuou.</Titulo>
    <Corpo>E essa ligação tomou outro rumo em maio de 2023, quando os pais do Caio perguntaram se ele queria assumir o sítio. Ocorre que o Caio nunca tinha trabalhado com eventos na vida...</Corpo>
  </Tela>
);

const T6 = () => (
  // v5: a churrasqueira em reforma de fundo, como as telas 4 e 8 (o recorte do cover já deixa a garrafa de fora)
  <Tela n={6} foto="churrasqueira-reforma.webp" gap={30}>
    <Legenda>A churrasqueira, em reforma</Legenda>
    <Titulo size={54}>Mesmo assim ele aceitou, porque enxergava potencial e sentia que aquele chão também era dele.</Titulo>
    <Corpo size={36}>Começou ouvindo os funcionários e quem ainda fazia festa ali, acompanhando os primeiros eventos de ponta a ponta.</Corpo>
  </Tela>
);

const T7 = () => (
  <Tela n={7} fundo="terra" gap={46}>
    <Titulo size={60}>E após visitar diversos espaços, ele percebeu que era tratado apenas como mais uma data.</Titulo>
    <Fio />
    <Corpo size={38}>E foi aí que ele percebeu, que se quisesse implementar no sítio, toda a conexão que ele trazia da infância, o Vale tinha que ser diferente.</Corpo>
    <Destaque size={52}>Mas quando que a festa deixa de ser só mais uma data?</Destaque>
  </Tela>
);

const T8 = () => (
  <Tela n={8} foto="decor-15anos.jpg" gap={34}>
    <Titulo size={46}>Em um aniversário, o aniversariante pediu a namorada em casamento. Ao saber disso, Caio enviou na semana seguinte um buquê de flores de parabéns ao casal.</Titulo>
    <Corpo size={36}>Em outra festa, montou uma sala pra anfitriã se preparar pra surpresa.</Corpo>
    <Destaque size={44}>Quando você sente que transferimos todo esse amor e carinho do Caio pelo Vale, para o seu evento.</Destaque>
  </Tela>
);

const T9 = () => (
  <Tela n={9} fundo="mata" gap={38}>
    <Copia foto={CAIO} largura={440} altura={600} />
    <Titulo size={52}>Esse alguém é o menino da borda da piscina, que agora recebe a sua festa.</Titulo>
    <Corpo>Quando o Caio diz que a gente não fecha uma venda, mas sim inicia um relacionamento, é de transferir todo o seu carinho pelo Vale, para o evento de cada cliente que estamos falando.</Corpo>
  </Tela>
);

// v5: no lugar da moldura vazia, uma festa do Vale inteira (a decoração dos 13 anos), com o "+" de "a sua entra aqui"
const DECOR13: Foto = { src: "decor-13anos.jpg", w: 1800, h: 2400 };
const T10 = () => (
  <Tela n={10} fundo="areia" gap={40}>
    <div style={{ position: "relative" }}>
      <Copia foto={DECOR13} largura={348} altura={464} />
      <div style={{ position: "absolute", right: -30, bottom: -26, width: 92, height: 92, borderRadius: "50%", background: TERRA, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 10px 24px rgba(181,82,25,0.35)" }}>
        <svg width="40" height="40" viewBox="0 0 44 44" fill="none" stroke={CREAM} strokeWidth="4.4" strokeLinecap="round">
          <path d="M22 6v32M6 22h32" />
        </svg>
      </div>
    </div>
    <Caps size={58} antes="Daqui pra frente, " em="esse álbum é seu também." />
    <Destaque size={36} corpo>Manda pelo direct a foto da sua festa no Vale, de qualquer época, que é com essas fotos que a gente vai abrir o Álbum do Vale.</Destaque>
  </Tela>
);

const TELAS = [T1, T2, T3, T4, T5, T6, T7, T8, T9, T10];

export const ValeAlbum: React.FC = () => {
  const Atual = TELAS[Math.min(useCurrentFrame(), TELAS.length - 1)];
  return <Atual />;
};

export const ALBUM_CAPA_FRAMES = 150;
export const ValeAlbumCapa: React.FC = () => <T1 video />;

import React from "react";
import { Composition, registerRoot } from "remotion";
import { ValeAlbumCapa, ALBUM_CAPA_FRAMES } from "./Album";

const Root: React.FC = () => (
  <>
    <Composition id="Vale-Album-Capa" component={ValeAlbumCapa} durationInFrames={ALBUM_CAPA_FRAMES} fps={30} width={1080} height={1350} />
  </>
);
registerRoot(Root);
